#pragma once
#include <cassert>
#include <condition_variable>
#include <deque>
#include <mutex>
#include <optional>
#include <utility>

namespace ws {

template<typename T>
class BlockDeque {
public:
    using Clock = std::chrono::steady_clock;

    BlockDeque(std::size_t capacity) noexcept : capacity_(capacity) {
        assert(capacity > 0);
    }

    ~BlockDeque() noexcept {
        Close();
    }

    void Clear() noexcept {
        std::unique_lock<std::mutex> locker(mtx_);
        ClearNoLock();
    }

    bool Empty() const noexcept {
        std::lock_guard<std::mutex> locker(mtx_);
        return deq_.empty();
    }

    bool Full() const noexcept {
        std::lock_guard<std::mutex> locker(mtx_);
        return deq_.size() >= capacity_;
    }

    std::size_t Size() const noexcept {
        std::lock_guard<std::mutex> locker(mtx_);
        return deq_.size();
    }

    std::size_t Capacity() const noexcept {
        return capacity_;
    }

    void PushBack(T item) noexcept {
        std::unique_lock<std::mutex> locker(mtx_);
        WaitForSpace(locker);
        deq_.push_back(std::move(item));
        producer_cond_.notify_one();
    }

    void PushFront(T item) noexcept {
        std::unique_lock<std::mutex> locker(mtx_);
        WaitForSpace(locker);
        deq_.push_front(std::move(item));
        producer_cond_.notify_one();
    }

    const T& Front() const noexcept {
        std::lock_guard<std::mutex> locker(mtx_);
        assert(!deq_.empty());
        return deq_.front();
    }

    const T& Back() const noexcept {
        std::lock_guard<std::mutex> locker(mtx_);
        assert(!deq_.empty());
        return deq_.back();
    }

    T& Front() noexcept {
        std::lock_guard<std::mutex> locker(mtx_);
        assert(!deq_.empty());
        return deq_.front();
    }

    T& Back() noexcept {
        std::lock_guard<std::mutex> locker(mtx_);
        assert(!deq_.empty());
        return deq_.back();
    }

    std::optional<T> Pop(std::optional<Clock::duration> time_out = std::nullopt) noexcept {
        std::unique_lock<std::mutex> locker(mtx_);
        if (time_out.has_value()) {
            consumer_cond_.wait_for(locker, *time_out, [this] { return !deq_.empty() || closed_; });
        } else {
            consumer_cond_.wait(locker, [this] { return !deq_.empty() || closed_; });
        }
        if (closed_ && deq_.empty()) {
            return std::nullopt;
        }
        T item = std::move(deq_.front());
        deq_.pop_front();
        producer_cond_.notify_one();
        return item;
    }

    void Flush() noexcept {
        consumer_cond_.notify_all();
    }

    void Close() noexcept {
        std::unique_lock<std::mutex> locker(mtx_);
        closed_ = true;
        ClearNoLock();
        producer_cond_.notify_all();
        consumer_cond_.notify_all();
    }

private:
    void WaitForSpace(std::unique_lock<std::mutex>& locker) noexcept {
        producer_cond_.wait(locker, [this] { return deq_.size() < capacity_ || closed_; });
    }

    void ClearNoLock() noexcept {
        deq_.clear();
    }

private:
    mutable std::mutex mtx_;
    std::atomic_bool closed_ {false};
    std::size_t capacity_;
    std::deque<T> deq_;
    std::condition_variable consumer_cond_;
    std::condition_variable producer_cond_;
};

}
